      }

      match /history/{historyId} {
        allow read: if canAccessTechnicalSupport();
        allow write: if false;
      }
    }

    match /supportCounters/{counterId} {
      allow read, write: if false;
    }

    match /technicalAssetLogs/{logId} {
      allow read: if canAccessTechnicalSupport();

      allow create: if canManageTechnicalSupport();

      allow update, delete: if false;
    }

    match /technicalMaintenances/{maintenanceId} {
      allow read: if canAccessTechnicalSupport();

      allow create, update: if canManageTechnicalSupport();

      allow delete: if isAdmin();
    }

    match /technicalLocations/{locationId} {
      allow read: if canAccessTechnicalSupport();

      allow create: if validTechnicalLocationCreate();

      allow update: if validTechnicalLocationUpdate();

      allow delete: if isAdmin();
    }

    match /technicalLocationReviews/{reviewId} {
      allow read: if canAccessTechnicalSupport();

      allow create: if validTechnicalLocationReviewCreate();

      allow update: if canManageTechnicalSupport();

      allow delete: if isAdmin();
    }

    match /technicalSpareParts/{partId} {
      allow read: if canAccessTechnicalSupport();

      allow create, update: if canManageTechnicalSupport();

      allow delete: if isAdmin();
    }

    match /technicalSparePartMovements/{movementId} {
      allow read: if canAccessTechnicalSupport();

      allow create: if canManageTechnicalSupport();

      allow update, delete: if false;
    }

    match /technicalInstallationTemplates/{templateId} {
      allow read: if canAccessTechnicalSupport();

      allow create, update: if canManageTechnicalSupport();

      allow delete: if isAdmin();
    }

    function isClosedTechnicalInstallation() {
      return resource.data.status == "completed" || resource.data.status == "cancelled";
    }

    function isCompletedTechnicalInstallation() {
      return resource.data.status == "completed";
    }

    function isInstallationEvidenceOnlyUpdate() {
      return request.resource.data.diff(resource.data).affectedKeys().hasOnly([
        "evidenceItems",
        "evidenceCount",
        "imageEvidenceCount",
        "videoEvidenceCount",
        "updatedAt",
        "updatedBy",
        "updatedByEmail",
        "updatedById"
      ]);
    }

    match /technicalInstallations/{installationId} {
      allow read: if canAccessTechnicalSupport();

      allow create: if canManageTechnicalSupport();

      allow update: if canManageTechnicalSupport()
        && (
          !isClosedTechnicalInstallation() ||
          isAdmin() ||
          (isCompletedTechnicalInstallation() && isInstallationEvidenceOnlyUpdate())
        );

      allow delete: if isAdmin();
    }




    function canReadIdea() {
      return isAdmin()
        || (
          hasProfile()
          && resource.data.createdByUid == request.auth.uid
        );
    }

    function canReadIdeaId(ideaId) {
      return isAdmin()
        || (
          hasProfile()
          && exists(/databases/$(database)/documents/ideas/$(ideaId))
          && get(/databases/$(database)/documents/ideas/$(ideaId)).data.createdByUid == request.auth.uid
        );
    }

    function validIdeaCreate() {
      return hasProfile()
        && request.resource.data.keys().hasOnly([
          "title",
          "category",
          "area",
          "currentProblem",
          "proposedIdea",
          "implementationSuggestion",
          "expectedBenefit",
          "priority",
          "impact",
          "evidenceFiles",
          "evidenceCount",
          "status",
          "createdByUid",
          "createdByName",
          "createdByEmail",
          "createdAt",
          "updatedAt",
          "updatedByUid",
          "updatedByName",
          "updatedByEmail",
          "reviewedAt",
          "reviewedByUid",
          "reviewedByName",
          "reviewedByEmail",
          "convertedProjectId"
        ])
        && request.resource.data.createdByUid == request.auth.uid
        && request.resource.data.updatedByUid == request.auth.uid
        && request.resource.data.title is string
        && request.resource.data.title.size() > 0
        && request.resource.data.area is string
        && request.resource.data.area.size() > 0
        && request.resource.data.currentProblem is string
        && request.resource.data.currentProblem.size() > 0
        && request.resource.data.proposedIdea is string
        && request.resource.data.proposedIdea.size() > 0
        && request.resource.data.implementationSuggestion is string
        && request.resource.data.expectedBenefit is string
        && request.resource.data.expectedBenefit.size() > 0
        && request.resource.data.priority in ["baja", "media", "alta", "urgente"]
        && request.resource.data.impact in ["bajo", "medio", "alto", "muy_alto"]
        && request.resource.data.evidenceFiles is list
        && request.resource.data.evidenceFiles.size() == 0
        && request.resource.data.evidenceCount == 0
        && request.resource.data.reviewedAt == null
        && request.resource.data.reviewedByUid == ""
        && request.resource.data.reviewedByName == ""
        && request.resource.data.reviewedByEmail == ""
        && request.resource.data.convertedProjectId == null
        && request.resource.data.status == "nueva";
    }

    function validIdeaOwnerEvidenceUpdate() {
      return hasProfile()
        && resource.data.createdByUid == request.auth.uid
        && request.resource.data.createdByUid == resource.data.createdByUid
        && request.resource.data.diff(resource.data).affectedKeys().hasOnly([
          "evidenceFiles",
          "evidenceCount",
          "updatedAt",
          "updatedByUid",
          "updatedByName",
          "updatedByEmail"
        ]);
    }

    match /ideas/{ideaId} {
      allow get, list: if canReadIdea();

      allow create: if validIdeaCreate();

      allow update: if isAdmin()
        || validIdeaOwnerEvidenceUpdate();

      allow delete: if isAdmin();

      match /comments/{commentId} {
        allow get, list: if canReadIdeaId(ideaId);

        allow create: if isAdmin()
          && request.resource.data.ideaId == ideaId
          && request.resource.data.comment is string
          && request.resource.data.comment.size() > 0
          && request.resource.data.createdByUid == request.auth.uid;

        allow update, delete: if false;
      }
    }

    match /bugReports/{reportId} {
      allow get, list: if canReadBugReport();

      allow create: if validBugReportCreate();

      allow update: if isAdmin()
        && request.resource.data.status is string
        && validBugReportStatus(request.resource.data.status);

      allow delete: if isAdmin();
    }


    match /purchaseRequests/{requestId} {
      allow get: if canReadPurchaseRequest();

      allow list: if isAdmin() || canReadPurchaseRequest();

      allow create: if validPurchaseRequestCreate();

      allow update: if validPurchaseAdminUpdate()
        || validPurchaseRequesterCancel();

      allow delete: if isAdmin();

      match /logs/{logId} {
        allow read: if canReadPurchaseRequestId(requestId);

        allow create: if validPurchaseLogCreate(requestId);

        allow update, delete: if false;
      }
    }

    match /projectInternalNotes/{noteId} {
      allow read: if isAdmin();

      allow create: if validInternalNoteCreate();

      allow update, delete: if false;
    }

    match /subscriptions/{subscriptionId} {
      allow read, create, update, delete: if isAdmin();
    }

    match /digitalSignageAssets/{assetId} {
      allow get: if isAdmin()
        || resource.data.active == true;
      allow list: if isAdmin();
      allow create, update, delete: if isAdmin();
    }

    match /digitalSignagePlaylists/{playlistId} {
      allow get: if isAdmin()
        || resource.data.active == true;
      allow list: if isAdmin();
      allow create, update, delete: if isAdmin();
    }

    match /digitalSignageCampaigns/{campaignId} {
      allow get, list: if true;
      allow create, update, delete: if isAdmin();
    }

    match /digitalSignageVisualTemplates/{templateId} {
      allow read, create, update, delete: if isAdmin();
    }

    match /digitalSignageAuditLogs/{logId} {
      allow read, create: if isAdmin();
      allow update, delete: if false;
    }

    match /digitalSignagePlaybackLogs/{logId} {
      allow read: if isAdmin();
      allow create: if request.resource.data.keys().hasOnly([
          "deviceId",
          "deviceTokenHash",
          "deviceName",
          "plantel",
          "location",
          "eventType",
          "assetId",
          "assetTitle",
          "assetType",
          "playlistId",
          "playlistName",
          "campaignId",
          "campaignName",
          "source",
          "durationSeconds",
          "errorMessage",
          "createdAt",
          "localTimestamp",
          "playerVersion"
        ])
        && request.resource.data.deviceId is string
        && request.resource.data.deviceId.size() > 0
        && request.resource.data.eventType in [
          "play_start",
          "play_end",
          "play_error",
          "playlist_resolved",
          "no_content",
          "offline_cache",
          "heartbeat_status"
        ]
        && request.resource.data.createdAt is timestamp
        && request.resource.data.createdAt <= request.time;
      allow update, delete: if false;
    }

    match /digitalSignageDevices/{deviceId} {
      allow get: if isAdmin()
        || resource.data.deviceToken == deviceId;
      allow list: if isAdmin();
      allow create: if isAdmin()
        && request.resource.data.deviceToken == deviceId;
      allow update: if isAdmin()
        || (
          resource.data.deviceToken == deviceId
          && request.resource.data.deviceToken == resource.data.deviceToken
          && request.resource.data.diff(resource.data).affectedKeys().hasOnly([
            "lastSeenAt",
            "lastSeenMillis",
            "updatedAt"
          ])
          && request.resource.data.lastSeenMillis is number
        );
      allow delete: if isAdmin();
    }

    match /editorialProjects/{projectId} {
      allow get: if canAccessEditorialProjectData(resource.data);
      allow list: if isAdmin();
      allow list: if hasProfile()
        && resource.data.ownerUid == request.auth.uid;
      allow list: if hasProfile()
        && request.auth.uid in resource.data.collaboratorUids;
      allow create: if validEditorialProjectCreate();
      allow update: if request.resource.data.ownerUid == resource.data.ownerUid
        && request.resource.data.createdAt == resource.data.createdAt
        && (
          isAdmin()
          || (hasProfile() && resource.data.ownerUid == request.auth.uid)
          || (
            isEditorialProjectCollaborator(resource.data)
            && request.resource.data.diff(resource.data).affectedKeys().hasOnly([
              "name",
              "type",
              "size",
              "orientation",
              "margins",
              "bleedIn",
              "widthIn",
              "heightIn",
              "academicMetadata",
              "seriesId",
              "seriesName",
              "levelId",
              "levelName",
              "bookId",
              "bookName",
              "unitNumber",
              "unitTitle",
              "lessonNumber",
              "lessonTitle",
              "academicType",
              "activityNumber",
              "updatedBy",
              "updatedAt"
            ])
          )
        );
      allow delete: if isAdmin()
        || (hasProfile() && resource.data.ownerUid == request.auth.uid);

      match /documents/{documentId} {
        allow read: if canAccessEditorialProject(projectId);
        allow create: if canCreateEditorialProjectChild(projectId);
        allow update, delete: if canEditEditorialContent(projectId);

        match /sections/{sectionId} {
          allow read: if canAccessEditorialProject(projectId);
          allow create: if canCreateEditorialProjectChild(projectId)
            || canEditEditorialContent(projectId);
          allow update, delete: if canEditEditorialContent(projectId);
        }

        match /pages/{pageId} {
          allow read: if canAccessEditorialProject(projectId);
          allow create: if canCreateEditorialProjectChild(projectId)
            || canEditEditorialContent(projectId);
          allow update, delete: if canEditEditorialContent(projectId);

          match /elements/{elementId} {
            allow read: if canAccessEditorialProject(projectId);
            allow create, update, delete: if canEditEditorialContent(projectId);
          }
        }

        match /masterPages/{masterPageId} {
          allow read: if canAccessEditorialProject(projectId);
          allow create, update, delete: if canEditEditorialContent(projectId);

          match /elements/{elementId} {
            allow read: if canAccessEditorialProject(projectId);
            allow create, update, delete: if canEditEditorialContent(projectId);
          }
        }

        match /comments/{commentId} {
          allow read: if canAccessEditorialProject(projectId);
          allow create, update, delete: if canCommentEditorial(projectId);
        }

        match /versions/{versionId} {
          allow read: if canAccessEditorialProject(projectId);
          allow create, update, delete: if canEditEditorialContent(projectId);
        }

        match /exports/{exportId} {
          allow read: if canAccessEditorialProject(projectId);
          allow create, update, delete: if canEditEditorialContent(projectId);
        }

        // Fase 7 — Publicaciones editoriales inmutables. Publicar/actualizar
        // estado requiere capacidad de publicación. No se permite delete: las
        // publicaciones se archivan, conservando historial y dependencias.
        match /publications/{publicationId} {
          allow read: if canAccessEditorialProject(projectId);
          allow create, update: if canPublishEditorial(projectId);
          allow delete: if false;
        }
      }

      match /components/{componentId} {
        allow read: if canAccessEditorialProject(projectId);
        allow create, update, delete: if canEditEditorialContent(projectId);

        match /elements/{elementId} {
          allow read: if canAccessEditorialProject(projectId);
          allow create, update, delete: if canEditEditorialContent(projectId);
        }
      }

      match /styles/{styleId} {
        allow read: if canAccessEditorialProject(projectId);
        allow create, update, delete: if canEditEditorialContent(projectId);
      }

      match /variables/{variableId} {
        allow read: if canAccessEditorialProject(projectId);
        allow create, update, delete: if canEditEditorialContent(projectId);
      }
    }

    match /editorialTemplates/{templateId} {
      allow read: if isAdmin()
        || (hasProfile() && resource.data.visibility == "institutional")
        || (
          resource.data.projectId is string
          && canAccessEditorialProject(resource.data.projectId)
        );
      allow create: if isAdmin()
        || (
          request.resource.data.visibility == "project"
          && request.resource.data.projectId is string
          && request.resource.data.ownerUid == request.auth.uid
          && canEditEditorialProject(request.resource.data.projectId)
        );
      allow update: if isAdmin()
        || (
          resource.data.visibility == "project"
          && request.resource.data.visibility == "project"
          && resource.data.ownerUid == request.auth.uid
          && request.resource.data.ownerUid == resource.data.ownerUid
          && request.resource.data.projectId == resource.data.projectId
          && canEditEditorialProject(resource.data.projectId)
        );
      allow delete: if isAdmin()
        || (
          resource.data.visibility == "project"
          && resource.data.ownerUid == request.auth.uid
          && canEditEditorialProject(resource.data.projectId)
        );

      match /pages/{pageId} {
        allow read: if canAccessEditorialTemplate(templateId);
        allow create, update, delete: if canEditEditorialTemplate(templateId);

        match /elements/{elementId} {
          allow read: if canAccessEditorialTemplate(templateId);
          allow create, update, delete: if canEditEditorialTemplate(templateId);
        }
      }
    }

    match /editorialAssets/{assetId} {
      allow read: if resource.data.projectId is string
        && canAccessEditorialProject(resource.data.projectId);
      allow create: if request.resource.data.projectId is string
        && request.resource.data.ownerUid == request.auth.uid
        && canEditEditorialProject(request.resource.data.projectId);
      allow update: if resource.data.projectId == request.resource.data.projectId
        && resource.data.ownerUid == request.resource.data.ownerUid
        && canEditEditorialProject(resource.data.projectId);
      allow delete: if canEditEditorialProject(resource.data.projectId);
    }

    match /digitalSignagePairingSessions/{sessionId} {
      allow get: if true;
      allow list: if isAdmin();
      allow create: if request.resource.data.keys().hasOnly([
          "code",
          "status",
          "deviceToken",
          "createdAt",
          "expiresAt",
          "claimedAt",
          "claimedBy",
          "userAgent",
          "lastSeenAt",
          "setupSecret"
        ])
        && request.resource.data.code is string
        && request.resource.data.code.matches("^AES-[0-9]{4,6}$")
        && request.resource.data.status == "pending"
        && request.resource.data.deviceToken == null
        && request.resource.data.createdAt is timestamp
        && request.resource.data.createdAt <= request.time
        && request.resource.data.expiresAt is timestamp
        && request.resource.data.expiresAt > request.time
        && request.resource.data.claimedAt == null
        && request.resource.data.claimedBy == ""
        && request.resource.data.userAgent is string
        && request.resource.data.lastSeenAt is timestamp
        && request.resource.data.lastSeenAt <= request.time
        && request.resource.data.setupSecret is string
        && request.resource.data.setupSecret.size() >= 16;
      allow update: if isAdmin()
        || (
          resource.data.status == "pending"
          && request.resource.data.status == resource.data.status
          && request.resource.data.setupSecret == resource.data.setupSecret
          && request.resource.data.diff(resource.data).affectedKeys().hasOnly([
            "lastSeenAt",
            "setupSecret"
          ])
          && request.resource.data.lastSeenAt is timestamp
        );
      allow delete: if isAdmin();
    }

    match /userDashboardPreferences/{userId} {
      allow get: if signedIn() && request.auth.uid == userId;
      allow list: if false;
      allow create: if signedIn()
        && request.auth.uid == userId
        && request.resource.data.ownerUid == userId
        && request.resource.data.version is int
        && request.resource.data.layout is list
        && request.resource.data.updatedAt is timestamp
        && request.resource.data.keys().hasOnly([
          "ownerUid",
          "version",
          "layout",
          "updatedAt"
        ]);
      allow update: if signedIn()
        && request.auth.uid == userId
        && resource.data.ownerUid == userId
        && request.resource.data.ownerUid == resource.data.ownerUid
        && request.resource.data.version is int
        && request.resource.data.layout is list
        && request.resource.data.updatedAt is timestamp
        && request.resource.data.diff(resource.data).affectedKeys().hasOnly([
          "version",
          "layout",
          "updatedAt"
        ]);
      allow delete: if signedIn() && request.auth.uid == userId;
    }

    match /{document=**} {
      allow read, write: if false;
    }
  }
}
